from starlette._utils import parse_authority
from starlette.datastructures import URL
from starlette.responses import PlainTextResponse, RedirectResponse
from starlette.types import ASGIApp, Receive, Scope, Send


class HTTPSRedirectMiddleware:
    def __init__(self, app: ASGIApp) -> None:
        self.app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] in ("http", "websocket") and scope["scheme"] in ("http", "ws"):
            url = URL(scope=scope)
            if not url.netloc:
                response = PlainTextResponse("Invalid host header", status_code=400)
                await response(scope, receive, send)
                return

            redirect_scheme = {"http": "https", "ws": "wss"}[url.scheme]
            parsed_authority = parse_authority(url.netloc)
            assert parsed_authority is not None
            host, port = parsed_authority
            normalized_port = port.lstrip("0") if port is not None else None
            netloc = host if normalized_port in ("80", "443") else url.netloc
            url = url.replace(scheme=redirect_scheme, netloc=netloc)
            response = RedirectResponse(url, status_code=307)
            await response(scope, receive, send)
        else:
            await self.app(scope, receive, send)
